CREATE TABLE accounts(id SMALLINT PRIMARY KEY CHECK(id IN(1,2)), username VARCHAR(255) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,nickname VARCHAR(255) NOT NULL,role VARCHAR(255) NOT NULL CHECK(role IN('ADMIN','MEMBER')));
CREATE TABLE memories(id UUID PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,title VARCHAR(255) NOT NULL,body TEXT NOT NULL,date DATE NOT NULL,city VARCHAR(255) NOT NULL DEFAULT '',tag VARCHAR(255) NOT NULL DEFAULT '',published BOOLEAN NOT NULL DEFAULT FALSE,public_visible BOOLEAN NOT NULL DEFAULT FALSE,public_summary VARCHAR(500) NOT NULL DEFAULT '',author VARCHAR(255),deleted_at TIMESTAMPTZ,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX memories_date ON memories(date DESC) WHERE deleted_at IS NULL;
CREATE INDEX memories_public ON memories(date DESC) WHERE published AND public_visible AND deleted_at IS NULL;
CREATE TABLE anniversaries(id UUID PRIMARY KEY,title VARCHAR(255) NOT NULL,date DATE NOT NULL,annual BOOLEAN NOT NULL DEFAULT FALSE,public_visible BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE places(id UUID PRIMARY KEY,city VARCHAR(100) NOT NULL,name VARCHAR(255) NOT NULL,longitude NUMERIC(12,8),latitude NUMERIC(12,8),coordinate_system VARCHAR(20) NOT NULL DEFAULT 'GCJ02');
CREATE TABLE memory_places(memory_id UUID REFERENCES memories(id),place_id UUID REFERENCES places(id),PRIMARY KEY(memory_id,place_id));
CREATE TABLE media(id UUID PRIMARY KEY,storage_key VARCHAR(255) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE memory_media(memory_id UUID REFERENCES memories(id),media_id UUID REFERENCES media(id),sort_order INTEGER NOT NULL DEFAULT 0,public_display BOOLEAN NOT NULL DEFAULT FALSE,PRIMARY KEY(memory_id,media_id));
CREATE TABLE albums(id UUID PRIMARY KEY,title VARCHAR(255) NOT NULL);
CREATE TABLE album_media(album_id UUID REFERENCES albums(id),media_id UUID REFERENCES media(id),sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(album_id,media_id));
CREATE TABLE jobs(id UUID PRIMARY KEY,media_id UUID REFERENCES media(id),status VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,lease_until TIMESTAMPTZ,available_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_log(id BIGSERIAL PRIMARY KEY,actor VARCHAR(255) NOT NULL,action VARCHAR(80) NOT NULL,resource_id UUID,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE SPRING_SESSION(PRIMARY_ID CHAR(36) PRIMARY KEY,SESSION_ID CHAR(36) NOT NULL,CREATION_TIME BIGINT NOT NULL,LAST_ACCESS_TIME BIGINT NOT NULL,MAX_INACTIVE_INTERVAL INT NOT NULL,EXPIRY_TIME BIGINT NOT NULL,PRINCIPAL_NAME VARCHAR(100));
CREATE UNIQUE INDEX SPRING_SESSION_IX1 ON SPRING_SESSION(SESSION_ID);
CREATE INDEX SPRING_SESSION_IX2 ON SPRING_SESSION(EXPIRY_TIME);
CREATE INDEX SPRING_SESSION_IX3 ON SPRING_SESSION(PRINCIPAL_NAME);
CREATE TABLE SPRING_SESSION_ATTRIBUTES(SESSION_PRIMARY_ID CHAR(36) NOT NULL REFERENCES SPRING_SESSION(PRIMARY_ID) ON DELETE CASCADE,ATTRIBUTE_NAME VARCHAR(200) NOT NULL,ATTRIBUTE_BYTES BYTEA NOT NULL,PRIMARY KEY(SESSION_PRIMARY_ID,ATTRIBUTE_NAME));
